/* Isolated workbench upgrade. Original home and opening remain unchanged. */
const orchardState={mode:'sample',annotations:true,selected:2,fruit:'persimmon',file:null,url:null,meta:null,scale:1,x:0,y:0,ticket:0};
const orchardExamples=[
 {box:[.004,.435,.126,.204],name:'青绿外观',grade:'未熟',color:'#9da775',note:'留意底色与颜色分布。绿色外观只是分级线索之一。'},
 {box:[.18,.468,.106,.17],name:'黄绿转色',grade:'转色期',color:'#c1b06d',note:'青绿与黄橙同时出现。实际等级需要由已验证模型判断。'},
 {box:[.288,.468,.094,.168],name:'橙色外观',grade:'着色期',color:'#d39457',note:'橙色逐渐铺开。光线和品种都会影响照片中的颜色。'},
 {box:[.403,.468,.095,.166],name:'充分着色',grade:'完熟',color:'#b96f50',note:'用于说明分级界面，不代表糖度、脱涩状态或适口性。'}
];
const orchardNames={persimmon:'柿子',apple:'苹果',pear:'梨',peach:'桃'};
recognize=function(){return `<div class="orchard-workbench">
<section class="ow-main" aria-labelledby="ow-title">
<div class="ow-landscape" aria-hidden="true"></div><div class="ow-heading"><div><p class="ow-eyebrow">TAIHANG / ORCHARD OBSERVATORY <span>太行 · 果实观察站</span></p><h1 id="ow-title">一枚果实，<em>细看成熟。</em></h1><p class="ow-intro">从太行山与红旗渠出发，让每一份成熟被认真看见。</p></div><div class="ow-status"><i></i> 本地观察模式 <small>检测模型待接入</small></div></div>
<div class="ow-workspace"><section class="ow-viewer" aria-label="果实图像观察区"><div class="ow-viewer-head"><div><span class="ow-dot"></span> 果实视野 <small id="ow-image-label">预设示例 / 非模型推理</small></div><button type="button" id="ow-annotation" aria-pressed="true">隐藏标注</button></div>
<div class="ow-stage" id="ow-stage" tabindex="0" aria-label="图像观察区，可拖放照片，使用加减键缩放"><div class="ow-image-fit" id="ow-image-fit"><div class="ow-image-transform" id="ow-image-transform"><img id="ow-photo" src="assets/persimmon.webp" alt="四种外观阶段的柿果展示照片" draggable="false"><div id="ow-boxes"></div></div></div><span class="ow-sample-label" id="ow-sample-label">预设标注 · 仅供界面体验</span><div class="ow-drop-hint">松开，载入你的果实照片</div><div class="ow-stage-empty" id="ow-stage-empty" hidden>选择一张照片，开始观察</div></div>
<div class="ow-toolbar"><div class="ow-zoom"><button id="ow-minus" aria-label="缩小图片">−</button><output id="ow-scale">100%</output><button id="ow-plus" aria-label="放大图片">＋</button><button id="ow-reset">适应画面</button></div><span id="ow-dimensions">原色显示 · 点击标记观察</span></div>
<div class="ow-actions"><button class="ow-primary" id="ow-upload">上传果实照片 <span>↗</span></button><button class="ow-secondary" id="ow-example">体验示例</button><button class="ow-text-btn" id="ow-remove" hidden>移除照片</button><input type="file" id="ow-file" accept="image/jpeg,image/png,image/webp" hidden><span>支持拖放 · JPG / PNG / WebP · 最大 15 MB</span></div><p class="ow-upload-status" id="ow-upload-status" role="status" aria-live="polite">先点选图中标记，看看不同的外观线索。示例不是检测结论。</p></section>
<aside class="ow-analysis" aria-label="成熟度观察与结果"><div class="ow-analysis-top"><span class="ow-eyebrow">OBSERVATION / 观察记录</span><span id="ow-mode">示例模式</span></div><h2>读懂果实的颜色。</h2><div class="ow-fruits" role="group" aria-label="果实品类">${Object.entries(orchardNames).map(([id,name])=>`<button data-ow-fruit="${id}" aria-pressed="${id===orchardState.fruit}">${name}${id!=='persimmon'?'<small>待开放</small>':''}</button>`).join('')}</div><p class="ow-scope" id="ow-scope">当前展示柿果四级外观分级示意</p><div id="ow-result" aria-live="polite"></div><button id="ow-detect" class="ow-detect" disabled>真实检测 · 模型待接入</button><p class="ow-boundary">外观分级不等于糖度、内部品质或脱涩检测。上传照片仅在当前浏览器中预览。</p>
<div class="ow-robot-companion"><button id="ow-robot" class="ow-robot" aria-label="和小禾互动，查看下一条拍照建议"><img src="assets/xiaohe-robot.png" alt="小禾，双叶传感器的果园巡检机器人"><span class="ow-robot-shadow"></span></button><div><span class="ow-robot-name">小禾 <i></i> 果园观察伙伴</span><p id="ow-robot-speech" aria-live="polite">选一颗果实，和我一起细看。</p><button id="ow-robot-tip" class="ow-text-btn">问问小禾 ↗</button></div></div></aside></div><div class="ow-bottomline"><span>01 / OBSERVE <b>清楚入镜，认真观察。</b></span><a href="#recognize/photo-guide" id="ow-guide-link">怎样拍得更清楚 ↓</a></div>
</section>
<section class="ow-guide" id="photo-guide" aria-labelledby="ow-guide-title"><div class="ow-guide-photo"><img src="assets/hongqi-real.jpg" alt="红旗渠青年洞与渠水实景" loading="lazy"><span>林州 · 红旗渠<br><small>WINDMEMORIES / CC BY-SA 4.0</small></span></div><div class="ow-guide-copy"><p class="ow-eyebrow">02 / BEFORE THE SHUTTER</p><h2 id="ow-guide-title">好判断，<br>从看清楚开始。</h2><p class="ow-guide-lead">让光线、距离和角度，帮助你留下清楚的果实细节。</p><div class="ow-guide-tabs" role="group" aria-label="拍摄建议"><button data-ow-tip="0" aria-pressed="true">01 光线</button><button data-ow-tip="1" aria-pressed="false">02 距离</button><button data-ow-tip="2" aria-pressed="false">03 遮挡</button></div><div id="ow-tip-detail" aria-live="polite"></div><div class="ow-mini-example"><img id="ow-tip-image" src="assets/persimmon.webp" alt="用于说明拍照方法的果实展示图" loading="lazy"><span>拍摄提示示意 · 非模型检测</span></div><button class="ow-secondary" id="ow-back-upload">准备好了，上传照片 ↗</button>${cineSources()}</div></section></div>`};
bindUpload=function(){
 const q=id=>document.getElementById(id), s=orchardState;let dragging=null,tipIndex=0;
 if(['persimmon','apple','pear','peach'].includes(location.hash.split('/')[1]))s.fruit=location.hash.split('/')[1];
 const photo=q('ow-photo'),stage=q('ow-stage');
 const tips=['试试均匀自然光，避开果皮上的强反光。','靠近一点，让果实轮廓完整、细节清楚。','减少枝叶和果实之间的遮挡，再拍一张。'];
 function speak(text){q('ow-robot-speech').textContent=text;const bot=q('ow-robot');bot.classList.remove('respond');void bot.offsetWidth;bot.classList.add('respond');setTimeout(()=>bot?.classList.remove('respond'),850)}
 function fit(){if(!photo.naturalWidth)return;const k=Math.min(stage.clientWidth/photo.naturalWidth,stage.clientHeight/photo.naturalHeight);q('ow-image-fit').style.width=photo.naturalWidth*k+'px';q('ow-image-fit').style.height=photo.naturalHeight*k+'px';paintZoom()}
 function paintZoom(){const maxX=Math.max(0,(q('ow-image-fit').clientWidth*s.scale-stage.clientWidth)/2),maxY=Math.max(0,(q('ow-image-fit').clientHeight*s.scale-stage.clientHeight)/2);s.x=Math.max(-maxX,Math.min(maxX,s.x));s.y=Math.max(-maxY,Math.min(maxY,s.y));q('ow-image-transform').style.transform=`translate(${s.x}px,${s.y}px) scale(${s.scale})`;q('ow-scale').textContent=Math.round(s.scale*100)+'%';q('ow-minus').disabled=s.scale<=1;q('ow-plus').disabled=s.scale>=3;stage.classList.toggle('zoomed',s.scale>1)}
 function reset(){s.scale=1;s.x=s.y=0;fit()}
 function result(){const sample=s.mode==='sample'&&s.fruit==='persimmon';q('ow-mode').textContent=sample?'示例模式':s.url?'本地预览':'待上传';q('ow-scope').textContent=s.fruit==='persimmon'?'柿果四级外观标签 · 以实际模型验证为准':orchardNames[s.fruit]+'为拓展品类，尚未接入对应模型。';q('ow-result').innerHTML=sample?`<div class="ow-result-title"><span>样例 ${String(s.selected+1).padStart(2,'0')}</span><small>人工预设 · 非模型结果</small></div><div class="ow-grade" style="--grade:${orchardExamples[s.selected].color}"><i></i><strong>${orchardExamples[s.selected].grade}</strong></div><p class="ow-grade-note">${orchardExamples[s.selected].note}</p><div class="ow-grade-track">${orchardExamples.map((e,i)=>`<button data-ow-select="${i}" aria-pressed="${s.selected===i}" style="--grade:${e.color}"><i></i>${e.grade}</button>`).join('')}</div><div class="ow-example-foot"><strong>04</strong><span>可点选的外观示意<br>无置信度与检测统计</span></div>`:`<div class="ow-await"><span class="ow-await-icon">◎</span><h3>${s.url?'照片已就绪':'等待一张果实照片'}</h3><p>${s.url?'可以缩放与拖动查看细节。模型尚未接入，当前没有成熟度结果。':'上传后可查看原图；也可以切回柿子品类体验预设标注。'}</p></div>`;q('ow-result').querySelectorAll('[data-ow-select]').forEach(b=>b.onclick=()=>select(+b.dataset.owSelect));q('ow-boxes').innerHTML=sample&&s.annotations?orchardExamples.map((e,i)=>`<button class="ow-box ${i===s.selected?'selected':''}" data-ow-select="${i}" style="left:${e.box[0]*100}%;top:${e.box[1]*100}%;width:${e.box[2]*100}%;height:${e.box[3]*100}%;--grade:${e.color}" aria-label="查看示例${i+1}，${e.grade}" aria-pressed="${i===s.selected}"><span data-number="0${i+1}">0${i+1} · ${e.grade}</span></button>`).join(''):'';q('ow-boxes').querySelectorAll('button').forEach(b=>b.onclick=()=>select(+b.dataset.owSelect));q('ow-annotation').disabled=!sample;q('ow-annotation').textContent=s.annotations?'隐藏标注':'显示标注';q('ow-annotation').setAttribute('aria-pressed',String(s.annotations));q('ow-sample-label').hidden=s.mode!=='sample';q('ow-remove').hidden=s.mode!=='upload';q('ow-image-label').textContent=s.mode==='sample'?'预设示例 / 非模型推理':'本地照片 / 未执行检测';document.querySelectorAll('[data-ow-fruit]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.owFruit===s.fruit)))}
 function select(i){s.selected=i;result();speak('这是“'+orchardExamples[i].grade+'”的界面示意，实际照片需要模型判断。')}
 function show(){photo.src=s.mode==='upload'&&s.url?s.url:'assets/persimmon.webp';photo.alt=s.mode==='upload'?'你上传的果实照片，原色预览':'柿子外观分级展示照片，人工预设示例';q('ow-dimensions').textContent=s.mode==='upload'&&s.meta?s.meta.width+' × '+s.meta.height+' px · 原色显示':'原色显示 · 点击标记观察';reset();result()}
 photo.onload=fit;const resize=new ResizeObserver(()=>{if(stage.isConnected)fit();else resize.disconnect()});resize.observe(stage);
 q('ow-plus').onclick=()=>{s.scale=Math.min(3,s.scale+.25);paintZoom()};q('ow-minus').onclick=()=>{s.scale=Math.max(1,s.scale-.25);paintZoom()};q('ow-reset').onclick=reset;stage.ondblclick=reset;
 stage.onkeydown=e=>{if(e.target!==stage)return;if(['+','=','-','0','ArrowLeft','ArrowRight','ArrowUp','ArrowDown'].includes(e.key)){e.preventDefault();if(e.key==='0')reset();else if(e.key==='+'||e.key==='=')s.scale=Math.min(3,s.scale+.25);else if(e.key==='-')s.scale=Math.max(1,s.scale-.25);else{const d={ArrowLeft:[30,0],ArrowRight:[-30,0],ArrowUp:[0,30],ArrowDown:[0,-30]}[e.key];s.x+=d[0];s.y+=d[1]}paintZoom()}};
 stage.onpointerdown=e=>{if(e.target.closest('button')||s.scale<=1||e.button!==0)return;dragging={id:e.pointerId,x:e.clientX,y:e.clientY,px:s.x,py:s.y};stage.setPointerCapture(e.pointerId)};stage.onpointermove=e=>{if(!dragging)return;s.x=dragging.px+e.clientX-dragging.x;s.y=dragging.py+e.clientY-dragging.y;paintZoom()};stage.onpointerup=stage.onpointercancel=()=>{dragging=null};
 q('ow-upload').onclick=()=>{q('ow-file').value='';q('ow-file').click()};
 function load(file){if(!file)return;const status=q('ow-upload-status');if(!['image/jpeg','image/png','image/webp'].includes(file.type)){status.textContent='请选择 JPG、PNG 或 WebP 图片。';return}if(file.size>15*1048576){status.textContent='图片超过 15 MB，请选择较小的文件。';return}const ticket=++s.ticket,url=URL.createObjectURL(file),im=new Image();status.textContent='正在读取图片…';im.onload=()=>{if(ticket!==s.ticket||!stage.isConnected){URL.revokeObjectURL(url);return}if(s.url)URL.revokeObjectURL(s.url);s.url=url;s.file=file;s.meta={width:im.naturalWidth,height:im.naturalHeight};s.mode='upload';show();status.textContent=file.name+' · 已在本地载入，未上传至服务器，未执行模型推理。';speak('照片收到了！先放大检查清晰度，真实检测等待模型接入。')};im.onerror=()=>{URL.revokeObjectURL(url);if(ticket===s.ticket&&stage.isConnected)status.textContent='无法读取这张图片，请更换文件。'};im.src=url}
 q('ow-file').onchange=e=>load(e.target.files[0]);['dragenter','dragover'].forEach(t=>stage.addEventListener(t,e=>{e.preventDefault();stage.classList.add('dragging')}));stage.addEventListener('dragleave',e=>{if(!stage.contains(e.relatedTarget))stage.classList.remove('dragging')});stage.addEventListener('drop',e=>{e.preventDefault();stage.classList.remove('dragging');load(e.dataTransfer.files[0])});
 q('ow-example').onclick=()=>{s.ticket++;s.mode='sample';s.fruit='persimmon';s.annotations=true;show();q('ow-upload-status').textContent='当前为人工预设的界面示例，不是你的照片检测结果。';speak('点一下果实标记，试试四级外观观察。')};
 q('ow-remove').onclick=()=>{s.ticket++;if(s.url)URL.revokeObjectURL(s.url);s.url=s.file=s.meta=null;s.mode='sample';s.fruit='persimmon';show();q('ow-upload-status').textContent='照片已移除，已返回预设示例。';speak('可以再放一张照片给我看看。')};
 q('ow-annotation').onclick=()=>{s.annotations=!s.annotations;result()};document.querySelectorAll('[data-ow-fruit]').forEach(b=>b.onclick=()=>{s.fruit=b.dataset.owFruit;result();speak(s.fruit==='persimmon'?'柿子示例可以帮助了解外观分级。':orchardNames[s.fruit]+'模型还未开放，可以先上传照片做本地观察。')});
 q('ow-robot').onclick=q('ow-robot-tip').onclick=()=>speak(tips[tipIndex++%tips.length]);q('ow-robot').onpointerenter=()=>q('ow-robot').classList.add('awake');q('ow-robot').onpointerleave=()=>q('ow-robot').classList.remove('awake');
 const guide=[['让自然光均匀落在果皮上。','避开直射高光与深重阴影。清楚保留表皮颜色，观察时不添加滤镜。','none'],['靠近，但保留完整轮廓。','保证果实在画面中有足够细节；拍摄前对焦，避免数码放大造成模糊。','none'],['让每颗果实，都能被看见。','换一个角度，减少枝叶遮挡和果实重叠。复杂场景需要额外验证。','none']];
 document.querySelectorAll('[data-ow-tip]').forEach(b=>b.onclick=()=>{const i=+b.dataset.owTip;document.querySelectorAll('[data-ow-tip]').forEach(x=>x.setAttribute('aria-pressed',String(x===b)));q('ow-tip-detail').innerHTML=`<h3>${guide[i][0]}</h3><p>${guide[i][1]}</p>`;q('ow-tip-image').style.objectPosition=['center','35% 55%','85% 55%'][i];q('ow-tip-image').style.transform=i===1?'scale(1.35)':'none'});document.querySelector('[data-ow-tip="0"]').click();
 q('ow-guide-link').onclick=e=>{e.preventDefault();q('photo-guide').scrollIntoView({behavior:reduced.matches?'auto':'smooth'})};q('ow-back-upload').onclick=()=>{q('ow-title').scrollIntoView({behavior:'auto',block:'start'});q('ow-upload').focus();q('ow-file').value='';q('ow-file').click()};show();
};
